create stage-tables   \ (by stage, which: volumes, bends, pans, sequence volumes)
    stage0-vols , stage0-bends , stage0-pans , stage0-seq-vols ,
    stage1-vols , stage1-bends , stage1-pans , stage1-seq-vols ,
    stage2-vols , stage2-bends , stage2-pans , stage2-seq-vols ,
    stage3-vols , stage3-bends , stage3-pans , stage3-seq-vols ,
: stage-table ( stage which -- addr )   \ which: 0 volumes, 1 bends, 2 pans, 3 sequence volumes
    swap dup 0 4 within 0= if  2drop stage0-vols exit  then
    swap dup 0 3 within 0= if  drop 3  then   \ (else the sequence volumes)
    swap 4 * + cells stage-tables + @ ;

\ the stage music's files (MusicStageN_Load): 0 the bank (.HD), 1..4 the sequences (panic,
\ calm A and B, chase), 5 the bank's samples (.BD)
strings: stage1-files  BGM\STAGE1_BANK.HD  BGM\PANIC.SQ  BGM\S1_NORMALA.SQ  BGM\S1_NORMALB.SQ  BGM\S1_CHASE.SQ  BGM\STAGE1_BANK.BD ;
strings: stage2-files  BGM\STAGE2_BANK.HD  BGM\PANIC.SQ  BGM\S2_NORMALA.SQ  BGM\S2_NORMALB.SQ  BGM\S2_CHASE.SQ  BGM\STAGE2_BANK.BD ;
strings: stage3-files  BGM\STAGE3_BANK.HD  BGM\PANIC.SQ  BGM\S3_NORMALA.SQ  BGM\S3_NORMALB.SQ  BGM\S3_CHASE.SQ  BGM\STAGE3_BANK.BD ;
strings: stage4-files  BGM\STAGE4_BANK.HD  BGM\PANIC.SQ  BGM\S4_NORMALA.SQ  BGM\S4_NORMALB.SQ  BGM\S4_CHASE.SQ  BGM\STAGE4_BANK.BD ;
: stage-file ( stage i -- addr len )
    swap case  0 of  stage1-files  endof  1 of  stage2-files  endof  2 of  stage3-files  endof
        3 of  stage4-files  endof  >r drop s" " r>  endcase ;
